package com.neu.riketiku.zhishikapian;
import static org.assertj.core.api.Assertions.assertThat;import com.neu.riketiku.aixuesheng.StudentAiService;import com.neu.riketiku.demo.DemoDataService;import com.neu.riketiku.tiku.admin.AdminQuestionIntegrationTestSupport;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
@SpringBootTest class KnowledgeCardIntegrationTest extends AdminQuestionIntegrationTestSupport{@Autowired DemoDataService demo;@Autowired KnowledgeCardService service;@Autowired StudentAiService ai;@Autowired JdbcTemplate jdbc;@Test @Transactional void aiDraftRequiresReviewAndStudentStateIsScoped(){demo.seed();long teacher=id("SELECT id FROM yong_hu WHERE yong_hu_ming='demo_physics_admin'"),student199=id("SELECT id FROM yong_hu WHERE yong_hu_ming='demo_199_01'"),student200=id("SELECT id FROM yong_hu WHERE yong_hu_ming='demo_200_01'"),scope=id("SELECT r.id FROM ren_ke_guan_xi r JOIN ban_ji b ON b.id=r.ban_ji_id JOIN jiao_shi_dang_an j ON j.id=r.jiao_shi_id WHERE b.ban_ji_bian_ma='DEMO_CLASS_199' AND j.yong_hu_id="+teacher+" AND r.ke_mu_id=(SELECT id FROM ke_mu WHERE ke_mu_dai_ma='PHYSICS')"),point=id("SELECT z.id FROM zhi_shi_dian z JOIN ke_mu k ON k.id=z.ke_mu_id WHERE k.ke_mu_dai_ma='PHYSICS' AND z.ceng_ji=3 ORDER BY z.id LIMIT 1");var card=service.create(teacher,scope,new KnowledgeCardDtos.Save("FORMULA","牛顿第二定律",List.of(point),"F=ma","F=ma","惯性参考系","合力产生加速度","不要把速度当成力","质量2kg受合力4N","合力除以质量","RIKE项目自编",null,"PROJECT_AUTHORED",1,true));assertThat(card.status()).isEqualTo("PENDING");assertThat(service.studentList(student199,null,null,null,null,null)).noneMatch(c->c.id().equals(card.id()));service.review(teacher,card.id(),new KnowledgeCardDtos.Review("APPROVE","来源和公式核验通过"));assertThat(service.studentList(student199,null,point,"FORMULA",null,null)).anyMatch(c->c.id().equals(card.id()));assertThat(service.studentList(student200,null,null,null,null,null)).noneMatch(c->c.id().equals(card.id()));var updated=service.state(student199,card.id(),new KnowledgeCardDtos.State(true,"MASTERED"));assertThat(updated.favorite()).isTrue();assertThat(updated.mastery()).isEqualTo("MASTERED");var conversation=ai.createConversation(student199,null,null,card.id(),"KNOWLEDGE_CARD",null,"STANDARD",false);assertThat(conversation.contextType()).isEqualTo("KNOWLEDGE_CARD");assertThat(conversation.knowledgeCardId()).isEqualTo(card.id());assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM gao_pin_kao_dian_shen_he_ji_lu WHERE gao_pin_kao_dian_id=?",Integer.class,card.id())).isEqualTo(2);assertThat(service.frequency(student199,card.id())).hasSize(2).allSatisfy(f->assertThat(f.sampleNotice()).contains("真题样本不足"));}long id(String sql){return jdbc.queryForObject(sql,Long.class);}}
